"""matplotlib.backend_tools — tool base classes."""

class ToolBase:
    default_keymap = None
    description = ''
    image = None
    def __init__(self, toolmanager, name): self.name = name
    def trigger(self, sender, event, data=None): pass
    def set_figure(self, figure): pass

class ToolToggleBase(ToolBase):
    radio_group = None
    cursor = None
    def enable(self, event=None): pass
    def disable(self, event=None): pass

class ToolSetCursor(ToolBase): pass
class ToolCursorPosition(ToolBase): pass
class ToolViewsPositions(ToolBase): pass
class ToolHome(ToolBase): pass
class ToolBack(ToolBase): pass
class ToolForward(ToolBase): pass
class SaveFigureBase(ToolBase): pass
class ZoomPanBase(ToolToggleBase): pass
class ToolZoom(ZoomPanBase): pass
class ToolPan(ZoomPanBase): pass
class ToolFullScreen(ToolToggleBase): pass
class ToolGrid(ToolBase): pass
class ToolMinorGrid(ToolBase): pass
class ToolCopyToClipboardBase(ToolBase): pass
class ToolHelpBase(ToolBase): pass
class ToolQuitAll(ToolBase): pass
class ToolQuit(ToolBase): pass
class ToolXScale(ToolBase): pass
class ToolYScale(ToolBase): pass

default_tools = {}
default_toolbar_tools = []


# ─── Added: missing public Tool classes from upstream ─────────────


class AxisScaleBase(ToolToggleBase):
    """Base for ``ToolXScale`` / ``ToolYScale`` toggle tools.
    Subclasses override ``enable``/``disable`` to flip a single axis
    between linear and log scaling."""

    def enable(self, event=None):  pass
    def disable(self, event=None): pass


class ConfigureSubplotsBase(ToolBase):
    """Base for the "Configure subplots..." toolbar action. Real
    matplotlib pops up a SubplotTool dialog; the shim is a no-op."""
    description = 'Configure subplots'


class RubberbandBase(ToolBase):
    """Base for tools that draw a rubber-band rectangle on the canvas
    (zoom-to-rect). The shim records the rectangle without rendering."""

    def draw_rubberband(self, *xy):
        self._last_band = tuple(xy)

    def remove_rubberband(self):
        self._last_band = None


class ViewsPositionsBase(ToolBase):
    """Base for tools that manage the back/forward navigation stack of
    axis view limits. Subclasses (Home/Back/Forward) push/pop entries
    on a private stack on the figure."""

    _positions = []  # class-level stack — matches upstream's shared behaviour

    def push_current(self):
        # Capture current view limits of every axes on the figure.
        figure = getattr(self.figmanager, 'canvas', None)
        if figure is None:
            return
        snap = []
        for ax in getattr(figure.figure, 'axes', []):
            try: snap.append((ax.get_xlim(), ax.get_ylim()))
            except Exception: snap.append(None)
        ViewsPositionsBase._positions.append(snap)


# Lowercase alias matching upstream's ``backend_tools.cursors`` constant.
from matplotlib.backend_bases import Cursors as _Cursors
cursors = _Cursors
# Re-export the class under its capitalised name (upstream uses both).
Cursors = _Cursors


def add_tools_to_container(container, tools=None):
    """Add a list of tools to a :class:`ToolContainerBase`. The shim's
    container is a placeholder, so we just collect the names."""
    if tools is None:
        tools = list(default_toolbar_tools)
    if not hasattr(container, '_added_tools'):
        container._added_tools = []
    container._added_tools.extend(tools)


def add_tools_to_manager(manager, tools=None):
    """Register every tool in ``tools`` (a dict mapping name → tool
    class) with the :class:`~matplotlib.backend_managers.ToolManager`."""
    if tools is None:
        tools = dict(default_tools)
    for name, tool_cls in tools.items():
        manager.add_tool(name, tool_cls)


