def _tvp_add_figure(self, figure): pass
def _tvp_back(self, *args):  return None
def _tvp_clear(self, figure): pass
def _tvp_forward(self, *args): return None
def _tvp_home(self, *args):    return None
def _tvp_push_current(self, *args): return None
def _tvp_refresh_locators(self):    pass
def _tvp_update_view(self):         pass

ToolViewsPositions.add_figure       = _tvp_add_figure
ToolViewsPositions.back             = _tvp_back
ToolViewsPositions.clear            = _tvp_clear
ToolViewsPositions.forward          = _tvp_forward
ToolViewsPositions.home             = _tvp_home
ToolViewsPositions.push_current     = _tvp_push_current
ToolViewsPositions.refresh_locators = _tvp_refresh_locators
ToolViewsPositions.update_view      = _tvp_update_view


# ─── Added: ToolBase common properties ──────────────────────────────


def _tb_canvas(self):
    return getattr(getattr(self, 'figure', None), 'canvas', None)
def _tb_figure_get(self):
    return getattr(self, '_figure', None)
def _tb_figure_set(self, fig):
    self._figure = fig
def _tb_toolmanager(self):
    return getattr(self, '_toolmanager', None)
def _tb_name(self):
    return getattr(self, '_name', '')

ToolBase.canvas      = property(_tb_canvas)
ToolBase.figure      = property(_tb_figure_get, _tb_figure_set)
ToolBase.toolmanager = property(_tb_toolmanager)
ToolBase.name        = property(_tb_name)


